Import ListNotations.
Open Scope bv_scope.
Local Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

(* [comment removed for export] *)
Definition apart_h (x nx y ny : Z) : Prop := x + nx <= y \/ y + ny <= x.

Definition cell : Type := (Z * nat * Z)%type.
Definition c_off (c : cell) : Z := fst (fst c).
Definition c_len (c : cell) : nat := snd (fst c).
Definition c_val (c : cell) : Z := snd c.

Section Cells.
Context {fx : FPState}.
Variable segs : list Segment.
#[local] Notation "'u'" := bv_unsigned (only parsing).

Definition cellsAt (m : word -> option byte) (base : Z) (L : list cell) : Prop :=
  Forall (fun c => rdn segs m (Z_to_bv 64 (base + c_off c)) (c_len c) = Some (Z_to_le_bytes (c_len c) (c_val c))) L.

(* [comment removed for export] *)
Definition agree_win (base len : Z) (RO : list (Z * Z)) (m m' : word -> option byte) : Prop :=
  forall a : word, base <= u a < base + len -> (forall r, In r RO -> ~ (base + fst r <= u a < base + fst r + snd r)) -> m' a = m a.

Definition cell_ok (len : Z) (RO : list (Z * Z)) (c : cell) : bool :=
  (0 <=? c_off c) && (c_off c + Z.of_nat (c_len c) <=? len) &&
  forallb (fun r => (c_off c + Z.of_nat (c_len c) <=? fst r) || (fst r + snd r <=? c_off c)) RO.

Lemma cells_keep : forall base len RO m m' L, 0 <= base -> base + len <= 2 ^ 64 -> agree_win base len RO m m' ->
  forallb (cell_ok len RO) L = true -> cellsAt m base L -> cellsAt m' base L.
Proof.
