Lemma agree_of_rinv : forall (R : list (Z * Z)) base len RO m m', rinv R m m' ->
  Forall (fun r => (fst r + snd r <= base \/ base + len <= fst r) \/
                   exists ro, In ro RO /\ base + fst ro <= fst r /\ fst r + snd r <= base + fst ro + snd ro) R ->
