Lemma LIVK_rdn : forall segs A (m m' : word -> option byte) (q : word) (k x : Z) (n : nat), LIVK A m m' -> live A q = Some k ->
  u q <= x -> x + Z.of_nat n <= u q + k -> u q + k <= 2 ^ 64 -> rdn segs m' (Z_to_bv 64 x) n = rdn segs m (Z_to_bv 64 x) n.
