(* [comment removed for export] *)
Ltac cell_from CS :=
  unfold word_to_le_bytes;
  lazymatch goal with
  | |- rdn _ _ (Z_to_bv 64 _) ?n = Some (Z_to_le_bytes ?n ?z) =>
    lazymatch type of CS with
    | cellsAt _ _ _ ?L =>
        let rec go k :=
          let o := eval cbv [nth_error] in (nth_error L k) in
          lazymatch o with
          | Some (?co, ?cn, ?cz) =>
              (* [comment removed for export] *)
              first [ (constr_eq cn n; constr_eq cz z; apply (cellsAt_nth _ _ _ L k (co, cn, cz) _ CS eq_refl); cbn [c_off fst]; lia) | go (Datatypes.S k) ]
          | None => fail 1 "cell_from: no cell of the bundle fits the goal"
          end in
        go 0%nat
    end
  end.

(* [comment removed for export] *)
Ltac keep_cells FC AG name :=
  lazymatch type of FC with
  | cellsAt ?sg ?m ?b ?L =>
      lazymatch type of AG with
      | agree_win _ ?len ?RO _ ?m' => pose proof (cells_keep sg b len RO m m' L ltac:(lia) ltac:(lia) AG ltac:(reflexivity) FC) as name
      end
  end.
